/* Knot, the shop's optional conversational guide. No chat history is persisted. */
(()=>{
const preferences={budget:null,priority:'value'},messages=[];
let pending=false,live=false,readAloud=false,opener=null,latestPhone=null,activeRequest=null;
const robot='assets/knot-robot.webp';
const launcher=document.createElement('button');launcher.id='knotLauncher';launcher.className='knot-launcher';launcher.setAttribute('aria-label','Talk to Knot, your shopping guide');launcher.setAttribute('aria-haspopup','dialog');launcher.setAttribute('aria-controls','knotPanel');launcher.setAttribute('aria-expanded','false');launcher.innerHTML=`<img src="${robot}" alt="" width="64" height="64"><span>Ask Knot<small>Your little tech guide</small></span>`;document.body.append(launcher);
const panel=document.createElement('dialog');panel.id='knotPanel';panel.className='knot-panel';panel.setAttribute('aria-labelledby','knotTitle');panel.innerHTML=`<div class="knot-header"><img class="knot-avatar" src="${robot}" alt="Knot, a friendly mint glass robot" width="64" height="64"><div><h2 id="knotTitle">A little help from Knot.</h2><span id="knotMood">Curious & ready to help</span></div><button class="knot-icon" data-knot-close aria-label="Close Knot">×</button></div><div class="knot-status"><span id="knotMode">Catalogue guide</span><button id="knotVoice" aria-pressed="false">Read aloud: off</button><button id="knotReset">New chat</button></div><div class="knot-messages" id="knotMessages" role="log" aria-label="Conversation with Knot" aria-live="polite" aria-relevant="additions"></div><div id="knotPrompts" class="knot-prompts"></div><form id="knotForm" class="knot-form"><label class="sr-only" for="knotInput">Your question for Knot</label><textarea id="knotInput" rows="1" maxlength="1200" placeholder="Your budget, your priorities…" required></textarea><button type="submit" id="knotSend" aria-label="Send question">↑</button></form><p class="knot-privacy">AI can make mistakes. Check manufacturer sources and shop details. When live AI is connected, your messages and selected products are sent to OpenAI. Avoid personal details.</p>`;document.body.append(panel);
const log=panel.querySelector('#knotMessages'),input=panel.querySelector('#knotInput'),form=panel.querySelector('form');
function context(){return{compare:location.hash.startsWith('#compare')?compareIds:[],product:latestPhone|| (location.hash.startsWith('#product/')?location.hash.split('/')[1]:null),bag:cart.map(x=>x.id)}}
function mood(value){panel.dataset.emotion=value;panel.querySelector('#knotMood').textContent={happy:'Happy to help you find your fit',curious:'Curious & ready to help',thoughtful:'Thinking through the little details',thinking:'Checking the details…'}[value]||'Ready to help'}
function productCards(ids){return ids.slice(0,3).map(id=>{const p=products.find(p=>p.id===id);return p?`<a class="knot-product" href="#product/${p.id}"><img src="assets/${p.image}" alt="" loading="lazy"><span><strong>${escapeHtml(p.name)}</strong><small>From ${money(p.price)} · demo</small><small>See details & sources →</small></span></a>`:''}).join('')}
function addMessage(role,text,ids=[]){const node=document.createElement('div');node.className='knot-message '+role;const label=document.createElement('small');label.textContent=role==='user'?'You':'Knot';const body=document.createElement('p');body.textContent=text;node.append(label,body);if(ids.length){const cards=document.createElement('div');cards.className='knot-products';cards.innerHTML=productCards(ids);node.append(cards)}log.append(node);log.scrollTop=log.scrollHeight;messages.push({role:role==='user'?'user':'assistant',content:text});if(messages.length>20)messages.splice(0,messages.length-20);if(role!=='user'&&readAloud&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.98;speechSynthesis.speak(u)}}
function prompts(){const compare=context().compare.length===2;panel.querySelector('#knotPrompts').innerHTML=(compare?['Explain these phones','Which is better for cameras?','Which is better for battery?']:['Under ৳70,000','I want a compact phone','Explain refresh rate','Help me build my kit']).map(t=>`<button type="button" data-knot-prompt="${escapeHtml(t)}">${escapeHtml(t)}</button>`).join('')}
function open(question){opener=document.activeElement;if(!panel.open){panel.showModal();launcher.setAttribute('aria-expanded','true')}prompts();if(!messages.length)addMessage('assistant','Hi, I’m Knot — your little tech guide. Tell me your budget and what you love doing on your phone. We’ll find a good fit together.');input.focus();if(question)send(question)}
function close(){if(panel.open)panel.close();if('speechSynthesis'in window)speechSynthesis.cancel();launcher.setAttribute('aria-expanded','false');opener?.focus?.()}
launcher.onclick=()=>open();panel.querySelector('[data-knot-close]').onclick=close;panel.addEventListener('close',()=>{launcher.setAttribute('aria-expanded','false');if('speechSynthesis'in window)speechSynthesis.cancel()});panel.addEventListener('click',e=>{const b=e.target.closest('[data-knot-prompt]');if(b)send(b.dataset.knotPrompt);if(e.target.closest('.knot-product'))close()});
async function send(text){if(pending||!text.trim())return;text=text.trim().slice(0,1200);const history=messages.slice(-8);addMessage('user',text);input.value='';pending=true;mood('thinking');panel.querySelector('#knotSend').disabled=true;panel.querySelectorAll('[data-knot-prompt]').forEach(b=>b.disabled=true);const thinking=document.createElement('div');thinking.className='knot-thinking';thinking.textContent='Knot is checking the details…';thinking.setAttribute('role','status');log.append(thinking);log.scrollTop=log.scrollHeight;let answer;const ctx=context();activeRequest=new AbortController();try{const response=await fetch('/api/advisor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,history,context:ctx}),signal:activeRequest.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Please try again in a moment.');if(data.available){answer=data;live=true}else{live=false;answer=knotGuide(text,ctx,preferences);if(data.temporary)answer.text='Live AI is taking a break. Here is catalogue guidance instead.\n\n'+answer.text}}catch(error){if(error.name==='AbortError')return;live=false;answer={...knotGuide(text,ctx,preferences)};answer.text='Live AI is unavailable right now. Here is catalogue guidance instead.\n\n'+answer.text}finally{thinking.remove();pending=false;panel.querySelector('#knotSend').disabled=false;panel.querySelectorAll('[data-knot-prompt]').forEach(b=>b.disabled=false)}if(answer){panel.querySelector('#knotMode').textContent=live?'Live AI · catalogue grounded':'Catalogue guide · live AI not connected';mood(answer.emotion);addMessage('assistant',answer.text,answer.productIds)}activeRequest=null}
form.onsubmit=e=>{e.preventDefault();send(input.value)};input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send(input.value)}};
panel.querySelector('#knotReset').onclick=()=>{activeRequest?.abort();messages.length=0;log.replaceChildren();preferences.budget=null;preferences.priority='value';latestPhone=null;addMessage('assistant','A fresh start. What is your budget, and what matters most to you?');prompts();mood('curious')};panel.querySelector('#knotVoice').onclick=e=>{readAloud=!readAloud;e.target.setAttribute('aria-pressed',String(readAloud));e.target.textContent='Read aloud: '+(readAloud?'on':'off');if(!readAloud&&'speechSynthesis'in window)speechSynthesis.cancel()};if(!('speechSynthesis'in window))panel.querySelector('#knotVoice').hidden=true;
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(Recognition){const mic=document.createElement('button');mic.type='button';mic.className='knot-mic';mic.textContent='Speak';mic.setAttribute('aria-label','Dictate a question. Your browser may process speech online.');form.insertBefore(mic,form.querySelector('#knotSend'));const recognition=new Recognition();recognition.lang='en-US';recognition.onresult=e=>{input.value=e.results[0][0].transcript;input.focus()};recognition.onend=()=>{mic.textContent='Speak';mic.disabled=false};recognition.onerror=()=>toast('Voice input is unavailable. You can type your question.');mic.onclick=()=>{try{recognition.start();mic.textContent='Listening…';mic.disabled=true}catch{toast('Voice input is unavailable')}};panel.addEventListener('close',()=>recognition.abort())}
function inject(){document.querySelectorAll('.knot-inline').forEach(x=>x.remove());let host=location.hash.startsWith('#compare')?main.querySelector('.lab-heading'):main.querySelector('.product-utilities');if(host){const b=document.createElement('button');b.className='chip knot-inline';b.dataset.knotExplain='';b.innerHTML=`<img src="${robot}" alt="" width="30" height="30"> ${location.hash.startsWith('#compare')?'Let Knot explain the differences':'Ask Knot about this phone'}`;host.append(b)}document.body.classList.toggle('knot-has-dock',!!document.getElementById('compareDock')&&!document.getElementById('compareDock').hidden);latestPhone=null}
const previousCompare=renderCompare;renderCompare=function(){previousCompare();inject()};
const previousRoute=renderRoute;renderRoute=function(){previousRoute();inject()};const previousPersist=persistCompare;persistCompare=function(){previousPersist();inject()};document.addEventListener('click',e=>{if(e.target.closest('[data-knot-explain]')){latestPhone=null;open(location.hash.startsWith('#compare')?'Explain these phones in simple terms, including who each is best for.':'Help me understand this phone and its trade-offs.')}});
const previousAdd=add;add=function(id){const before=cart.reduce((n,x)=>n+x.qty,0);previousAdd(id);const p=products.find(p=>p.id===id);if(p?.category==='Phones'&&cart.reduce((n,x)=>n+x.qty,0)>before)showKit(p)};
function showKit(phone){document.getElementById('knotKit')?.remove();latestPhone=phone.id;const kit=document.createElement('aside');kit.id='knotKit';kit.className='knot-kit';kit.setAttribute('aria-label','Optional accessories for your phone');kit.innerHTML=`<div class="knot-kit-head"><img src="${robot}" alt="" width="60" height="60"><div><small>KNOT’S LITTLE EXTRAS</small><h3>Your phone’s in. Need a kit?</h3></div><button class="knot-icon" aria-label="Dismiss accessory suggestions">×</button></div><p>For ${escapeHtml(phone.name)}. Optional, with exact fit and stock to confirm.</p><div class="knot-kit-items">${knotKit(phone).filter(x=>!cart.some(c=>c.id===x.product.id&&(!x.product.compatible||c.variant==='For '+phone.name))).map(({product:p,note})=>`<a href="#product/${p.id}" class="knot-kit-item"><img src="assets/${p.image}" alt=""><span><b>${escapeHtml(p.name)}</b><small>${money(p.price)} · demo</small><small>${escapeHtml(note)}</small></span><span>→</span></a>`).join('')||'<p>You already have these kit options in your bag.</p>'}</div><button class="chip" data-kit-help>Help me choose accessories →</button>`;document.body.append(kit);kit.querySelector('.knot-icon').onclick=()=>kit.remove();kit.querySelector('[data-kit-help]').onclick=()=>{kit.remove();open('Which case, protector and charger should I consider for '+phone.name+'?')};kit.querySelectorAll('a').forEach(a=>a.onclick=()=>kit.remove());if(!reduceMotion())kit.animate([{opacity:0,transform:'translateY(20px) scale(.97)'},{opacity:1,transform:'none'}],{duration:450,easing:'cubic-bezier(.16,1,.3,1)'})}
const baseBag=renderBag;renderBag=function(){baseBag();const phone=products.find(p=>cart.some(c=>c.id===p.id)&&p.category==='Phones');if(phone){const host=document.getElementById('bagContent');const b=document.createElement('button');b.className='chip knot-bag-help';b.textContent='Ask Knot about protection & charging →';b.onclick=()=>{document.getElementById('bagDialog').close();latestPhone=phone.id;open('Help me choose accessories for '+phone.name)};host.append(b)}};
window.addEventListener('hashchange',()=>{document.getElementById('knotKit')?.remove();if(panel.open)prompts()});
fetch('/api/advisor').then(r=>r.json()).then(d=>{live=!!d.available;panel.querySelector('#knotMode').textContent=live?'Live AI · catalogue grounded':'Catalogue guide · live AI not connected'}).catch(()=>{});inject();
})();
